property.value:
let $keyCalls := ('get', 'put', 'containsKey', 'remove', 'getOrDefault', 'putIfAbsent', 'computeIfAbsent',
                  'computeIfPresent', 'compute', 'merge', 'add', 'contains'),
    $plain := function($e) {
      exists($e[pmd-java:typeIsExactly('java.lang.String')][not(@CompileTimeConstant = true())]
        [not(self::MethodCall[@MethodName = ('toString', 'valueOf', 'name', 'toHexString', 'toBinaryString', 'toOctalString')])]
        [not(matches(string-join(descendant-or-self::*/(@Name, @MethodName), ' '), '(?:^|[a-z0-9])(?:id|Id|ID|uuid|Uuid|hash|Hash|index|Index|idx)( |$)', ''))]
        [not(matches(string-join(descendant-or-self::*/(@Name, @MethodName), ' '), '(?:^|[a-z0-9])(?:owner|Owner|class|Class|method|Method|bean|Bean)( |$)', ''))])
    },
    $generated := function($e) {
      exists($e/descendant-or-self::MethodCall[@MethodName = ('getAndIncrement', 'incrementAndGet', 'nanoTime', 'currentTimeMillis', 'randomUUID', 'nextLong', 'nextInt')])
    },
    $dynamic := function($e) { exists($e[not(@CompileTimeConstant = true())][not(self::StringLiteral)]) },
    $delimiter := function($e) { exists($e[self::StringLiteral][matches(@Image, '^"[-_:;,.|/#@~=*&%+]{1,2}"$')]) },
    $joinedExpr := function($e) {
      not($generated($e)) and
      exists($e/descendant-or-self::InfixExpression[@Operator = '+'][not(ancestor::ArgumentList[(.. is $e) or ancestor::*[. is $e]])]
               [*[1][self::InfixExpression[@Operator = '+'][$delimiter(*[2])][$dynamic(*[1])]]][$plain(*[2])][$plain(*[1]/*[1])]
             | $e[self::MethodCall][@MethodName = 'join'][pmd-java:matchesSig('java.lang.String#join(_*)')]
                 [$delimiter(ArgumentList/*[1])][count(ArgumentList/*[position() > 1][$plain(.)]) >= 2])
    },
    $joined := function($key) {
      $joinedExpr($key)
      or exists($key[self::VariableAccess][let $name := @Name return
           ancestor::*[self::MethodDeclaration or self::ConstructorDeclaration or self::LambdaExpression or self::Initializer][1]
             //LocalVariableDeclaration/VariableDeclarator[VariableId/@Name = $name][$joinedExpr(*[2])]])
    }
return //MethodCall[@MethodName = $keyCalls][*[1][pmd-java:typeIs('java.util.Map') or pmd-java:typeIs('java.util.Set')]]
  [let $key := ArgumentList/*[1] return $joined($key)]
